<template><AccountLayout bare><main class="hs"><header><h1>Help &amp; Support</h1><div>Account Number: AC-{{String(authState.user?.id||0).padStart(6,'0')}}<small>Last Updated: {{date(new Date())}}</small></div></header><section><h2>1. Ticket Info</h2><div class="info"><span>Ticket No.<b>New Ticket</b></span><span>Date<b>{{date(new Date())}}</b></span><span>Time<b>{{time(new Date())}}</b></span><span>Status<b>New Ticket</b></span><span>Priority<b>{{form.priority}}</b></span><span>Responded<b>● No</b></span></div></section><section><h2>2. Ticket Type</h2><div class="types"><button v-for="x in types" :class="{active:form.ticket_type===x}" @click="form.ticket_type=x">{{x}}</button></div></section><section><h2>3. Ticket Details</h2><form @submit.prevent="submit"><div class="fields"><label>Requested By<input v-model="form.requested_by" required></label><label>Position / Role<input v-model="form.position"></label><label>Email Address<input v-model="form.email" required type="email"></label><label>Phone Number<input v-model="form.phone"></label></div><label>Subject<input v-model="form.subject" required></label><label>Description<textarea v-model="form.description" required></textarea></label><label class="conf"><input v-model="form.confidential" type="checkbox"> Confidential — Request Management Review <small>Complaints and staff concerns can be routed directly to Management Review.</small></label><footer><button type="button" @click="reset">Cancel</button><button class="primary">Submit Ticket</button></footer></form></section><section><h2>4. My Support Tickets</h2><div class="table"><table><thead><tr><th>Ticket No.</th><th>Date</th><th>Type</th><th>Subject</th><th>Priority</th><th>Status</th><th>Responded</th><th>Action</th></tr></thead><tbody><tr v-for="t in tickets" :key="t.id"><td>{{t.ticket_no}}</td><td>{{date(t.created_at)}}</td><td>{{t.ticket_type}}</td><td>{{t.subject}}</td><td>{{t.priority}}</td><td>{{t.status}}</td><td>{{t.responded_at?'Yes':'No'}}</td><td><button @click="alert(t.description)">View Details</button></td></tr></tbody></table></div></section></main></AccountLayout></template>
<script setup>import{reactive,ref,onMounted}from'vue';import AccountLayout from'../components/AccountLayout.vue';import client from'../api/client';import{authState}from'../store/auth';const types=['Billing','Accounting','Technical Support','Report an Issue','Complaint','Share an Idea','Staff Feedback or Concern'];const tickets=ref([]);const base=()=>({ticket_type:'Technical Support',requested_by:authState.user?.name||'',position:'',email:authState.user?.email||'',phone:authState.user?.phone||'',subject:'',description:'',priority:'High',confidential:false});const form=reactive(base());const date=x=>new Intl.DateTimeFormat('en-US',{month:'long',day:'numeric',year:'numeric'}).format(new Date(x));const time=x=>new Intl.DateTimeFormat('en-US',{hour:'numeric',minute:'2-digit'}).format(new Date(x));const load=async()=>tickets.value=(await client.get('/account/support-tickets')).data.data;const reset=()=>Object.assign(form,base());const submit=async()=>{await client.post('/account/support-tickets',form);reset();load()};onMounted(load)</script>
<style scoped>.hs{max-width:1280px;margin:auto;padding:14px 22px;color:#061a8f}.hs header{display:flex;align-items:center;gap:35px}.hs h1,.hs h2{margin:0;color:#fff;background:linear-gradient(100deg,#073d79,#01225e);border-radius:5px}.hs h1{flex:1;padding:4px 22px;font-size:2.25rem}.hs header>div{text-align:right}.hs small{display:block;margin-top:5px}section{margin-top:10px;border:1px solid #cbd7e7;border-radius:5px;overflow:hidden;background:#fff}h2{padding:5px 15px;font-size:1.06rem}.info{display:grid;grid-template-columns:repeat(6,1fr);padding:10px}.info span{padding-left:25px;border-right:1px solid #cbd4e1}.info b{display:block;margin-top:7px;font-weight:400}.types{display:grid;grid-template-columns:repeat(4,1fr);gap:10px;padding:10px}.types button,footer button,td button{padding:9px;border:1px solid #c2cbdb;border-radius:5px;background:#fff;color:#061a8f;font:inherit}.types .active,footer .primary{border-color:#0755ed;color:#0755ed}.fields{display:grid;grid-template-columns:repeat(4,1fr);gap:20px}form{padding:8px 16px}label{display:block;margin:5px 0;color:#111}input,textarea{width:100%;height:33px;border:1px solid #b8c5d9;border-radius:5px}textarea{height:38px;resize:vertical}.conf input{width:22px;height:22px;vertical-align:middle}.conf small{margin-left:30px;color:#333}footer{display:flex;justify-content:flex-end;gap:15px;margin:8px 0}footer button{min-width:145px;border-color:#0755ed}footer .primary{background:#0755ed;color:#fff}table{width:100%;border-collapse:collapse;text-align:center;font-size:.88rem}th,td{padding:6px;border:1px solid #d4ddea;font-weight:400}th{background:#f3f7ff}.table{overflow:auto}@media(max-width:800px){.hs{padding:10px}.hs header{display:block}.hs header>div{text-align:left;margin:7px}.info{grid-template-columns:repeat(2,1fr);gap:8px}.types,.fields{grid-template-columns:1fr 1fr}table{min-width:850px}}</style>
